const content = $json.choices?.[0]?.message?.content;
if (!content) throw new Error('Orchestrator Agent did not return any content.');

let parsed;
try {
  parsed = JSON.parse(content);
} catch (error) {
  throw new Error(`Orchestrator returned invalid JSON: ${content}`);
}

return [{
  json: {
    request: $node['Prepare user request'].json.request,
    project_context: $node['Build Project Context'].json.project_context,
    intent: parsed.intent || 'unknown',
    reason: parsed.reason || ''
  }
}];

// Get all 12 baseline evaluation test cases
const testCases = $items('Build Project Context1');

// Get the complete project context
const projectContext =
  $node['Build Project Context'].json.project_context;

// Create one evaluation input for each test case
return testCases.map(testCase => ({
  json: {
    ...testCase.json,
    project_context: projectContext
  }
}));

