const items = $input.all();

return items.map((item, index) => {
  const raw = item.json.choices?.[0]?.message?.content ?? '';

  let result;

  try {
    result = JSON.parse(raw);
  } catch (e) {
    result = {
      pass: false,
      score: 0,
      reasons: ['Evaluator returned invalid JSON'],
      missing_or_invented_facts: [raw]
    };
  }

  return {
    json: {
      test_id: `T${index + 1}`,
      pass: result.pass ?? false,
      score: Number(result.score ?? 0),
      reasons: result.reasons ?? [],
      missing_or_invented_facts: result.missing_or_invented_facts ?? []
    }
  };
});

