const specialistResults = $input.all();
const originalTests = $items('Prepare Evaluation Agent Input');

return specialistResults.map((item, index) => {
  const raw = item.json.choices?.[0]?.message?.content ?? '';

  let answer;

  try {
    answer = JSON.parse(raw);
  } catch (e) {
    answer = {
      answer: raw
    };
  }

  const original = originalTests[index]?.json ?? {};

  return {
    json: {
      id: original.id || `T${index + 1}`,
      type: original.type || '',
      input: original.input || '',
      criteria: original.criteria || [],
      mode: original.mode || '',

      answer: answer.answer ?? '',
      evidence_used: answer.evidence_used ?? [],
      insufficient_data: answer.insufficient_data ?? false,

      project_context:
        original.project_context ||
        $node['Build Project Context'].json.project_context
    }
  };
});

