const items = $input.all();

// Determine which trigger started this execution
let entryPoint = 'unknown';

try {
  const evalRequest = $node['Evaluation trigger']?.json;
  if (evalRequest) {
    entryPoint = 'evaluation';
  }
} catch (e) {}

try {
  const miraRequest = $node['Mira API']?.json;
  if (miraRequest) {
    entryPoint = 'mira';
  }
} catch (e) {}

// Collect project data
const descriptionItem = items.find(i => i.json.source === 'description');
const timeline = items
  .filter(i => i.json.source === 'timeline')
  .map(i => i.json.data);

const risks = items
  .filter(i => i.json.source === 'risks')
  .map(i => i.json.data);

const tasks = items
  .filter(i => i.json.source === 'tasks')
  .map(i => i.json.data);

const description = descriptionItem?.json?.data || '';

return [{
  json: {
    project_context: {
      description,
      timeline,
      risks,
      tasks,
      sources: {
        description: 'project_description.txt',
        timeline: 'project_timeline.csv',
        risks: 'project_risks.csv',
        tasks: 'sample_task_board.csv'
      }
    },
    entry_point: entryPoint
  }
}];
